"""Ukrainian five-option sets 6–8 (level 3) for mock variants 6–8. Writes src/content/21-ukr-five-2.json.
Stress items are checked against the official ЛРЦОЯО list stored in src/data.json."""
import json, os, random, re, sys

sys.stdout.reconfigure(encoding='utf-8')
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
Q = []


def q(topic, prompt, correct, wrong, explanation):
    assert len(wrong) == 4 and correct not in wrong
    qid = f'ukr-five-20261021-{len(Q) + 1:02d}'
    opts = [correct] + wrong
    order = list(range(5))
    random.Random(qid).shuffle(order)
    Q.append({'id': qid, 'subject': 'ukr', 'topicId': topic, 'type': 'single', 'prompt': prompt,
              'options': [opts[i] for i in order], 'answer': order.index(0), 'explanation': explanation,
              'level': 3, 'tags': ['five-options', topic.split('-', 1)[1]]})


