assert len(Q) == 45
# Stress items: every marked word must match the official list.
data = json.load(open(os.path.join(ROOT, 'src', 'data.json'), encoding='utf-8'))
official = {}
for e in data['stressReference']['entries']:
    official.setdefault(e['word'], set()).update(e['answers'])
for x in Q:
    if x['topicId'] != 'ukr-sounds':
        continue
    good = x['options'][x['answer']]
    for opt in x['options']:
        marks = [re.sub(r'\s*\(.*?\)', '', w).strip() for w in opt.split(',')]
        ok = all(m in official.get(m.replace('́', ''), set()) for m in marks)
        assert ok == (opt == good), (x['id'], opt, ok)
    print('stress ok', x['id'])
sets = [[x['id'] for x in Q[i:i + 15]] for i in (0, 15, 30)]
out = os.path.join(ROOT, 'src', 'content', '21-ukr-five-2.json')
json.dump({'topicQuestions': Q, 'extend': {'ukrainianFiveOptionSets': sets}}, open(out, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
print(out, 'keys', [x['answer'] for x in Q])
